scripts.张琳心对话.txt:
// 与张琳心的同伴对话

	If ($Event == 420) @Event420;
	If ($Event == 421) @Event421;			//已经去过韩世忠大营，尚未去岳飞大营
	If ($Event == 430) @Event430;			//两个军营都已去过
	If ($Event == 440) @Event440;
	If ($Event >= 695) @Event695;
	
	Return;
	
@Event420:	
	If ($Talkyueyun == 0) @Eventyueyun0;	//两个军营都未去
	If ($Talkyueyun == 1) @Eventyueyun1;	//已经去过岳飞大营，尚未去韩世忠大营	
@Eventyueyun0:
	Say("独孤剑：这里有一个分叉路口。", 1);
	Say("张琳心：左边的路口是通往岳飞大营的，右边的路口是通往韩世忠大营的。", 21);
	Return;	
@Eventyueyun1:	
	Say("张琳心：我们去韩世忠大营吧。", 21);
	Return;	


@Event421:
	Say("张琳心：我们去岳飞大营吧。", 21);	// 此时 $Talkyueyun 的值只可能是0，如果是1，$Event 已经变成 430
	Return;		

	
@Event430:
	Say("张琳心：我们回朱仙镇吧！", 21);
	Return;	
	
@Event440:
	If ($Talkliuyun == 0) @Eventliuyun0;	// 没有和刘云说话
	If ($Talkliuyun == 1) @Eventliuyun1;	// 已经和刘云说过话：一种是没有红玉，另一种是已经去过库房
@Eventliuyun0:
	Say("张琳心：今天的天气真好！", 21);
	Return;
@Eventliuyun1:
	Say("张琳心：我们去岳飞大营吧！", 21);
	Return;	

@Event695:
	Say("张琳心：独孤哥哥，我们快去岳飞大营吧。",21);
	Return;

